def ols(y, X):
    X = np.column_stack([np.ones(len(y)), X]).astype(float)
    beta, *_ = np.linalg.lstsq(X, y, rcond=None)
    r_ = y - X@beta
    s2 = r_@r_/(len(y)-X.shape[1])
    cov = s2*np.linalg.pinv(X.T@X)
    return beta, np.sqrt(np.diag(cov))
